import{_ as t,l as n,o as e,c as s,v as o,p as i,x as r,d as p,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"杠杆周期 Geanakoplos","description":"","frontmatter":{"title":"杠杆周期 Geanakoplos","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/leverage-cycle.md","filePath":"econ/leverage-cycle.md","lastUpdated":1789023840000}'),d={name:"econ/leverage-cycle.md"};function h(B,a,m,A,_,u){const l=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="杠杆周期-geanakoplos" tabindex="-1">杠杆周期 Geanakoplos <a class="header-anchor" href="#杠杆周期-geanakoplos" aria-label="Permalink to &quot;杠杆周期 Geanakoplos&quot;">​</a></h1><div class="epigraph"><p>杠杆是内生证券：乐观者用多少抵押买风险，由谁的信念在边际上决定；繁荣时杠杆升，崩溃时 haircut 跳。</p><footer>—— Geanakoplos, The Leverage Cycle, NBER Macroeconomics Annual, 2010</footer></div><p><a href="/econ/market-funding-liquidity">上一课</a>把保证金写成波动的函数，规则可以外生。本课缺口是<strong>保证金本身由均衡决定</strong>：异质信念或异质估值下，抵押合同是被交易的对象，杠杆周期可以在没有新信息的波动规则下出现。不重画流动性螺旋的流程图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Geanakoplos：同一风险资产，悲观者不想持有，乐观者想加杠杆买。无摩擦完全市场会用 Arrow 证券把意见差异变成赌注；缺列时，抵押债是可用的赌注形式——违约时交割资产。均衡杠杆（或 haircut）由边际上的信念分布决定：越乐观的人越愿意出更低保证金来持有。好消息使资产涨、乐观者变富、杠杆再升；坏消息使抵押品跌、强制平仓、杠杆收缩，价格跌过基本面信念更新本身。缺口是把 BP 的保证金从「VaR 规则」换成「抵押市场出清」。</p><p>与 <a href="/econ/incomplete-markets-gei">不完全市场 GEI</a> 一脉：缺列时合同的形式（抵押、违约）改变实际张成。本课特化到杠杆作为内生列。</p><p><span class="marginnote">Geanakoplos, <em>NBER Macro Annual</em> 2010；更早的 Cowles 与 2003 文已经写抵押均衡。Fostel–Geanakoplos 把抵押一般均衡（CCE）写成系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期或有限树，异质先验。可交易：资产、无风险债、以资产为抵押的债（违约时收回抵押）。出清同时决定资产价格、利率与保证金。乐观者在抵押约束上，悲观者持有债。比较静态：信念或财富再分配改变均衡杠杆，反馈进价格。不必有中介机构——家庭之间的抵押已经够用；有中介时，专家是最乐观或最能估值的那一层。</p>',9)),(e(),i(E,null,{default:r(()=>[c(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HET%5B%22%E5%BC%82%E8%B4%A8%E4%BF%A1%E5%BF%B5%22%5D%20--%3E%20MORT%5B%22%E6%8A%B5%E6%8A%BC%E5%80%BA%E4%BD%9C%E4%B8%BA%E8%B5%8C%E6%B3%A8%22%5D%0A%20%20MORT%20--%3E%20LEV%5B%22%E5%9D%87%E8%A1%A1%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20BOOM%5B%22%E6%B6%A8%20%E2%86%92%20%E4%B9%90%E8%A7%82%E6%9B%B4%E5%AF%8C%20%E2%86%92%20%E6%9D%A0%E6%9D%86%E5%86%8D%E5%8D%87%22%5D%0A%20%20LEV%20--%3E%20BUST%5B%22%E8%B7%8C%20%E2%86%92%20%E5%B9%B3%E4%BB%93%20%E2%86%92%20%E6%9D%A0%E6%9D%86%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>不要把内生 haircut 写成交易所保证金的制度史。制度可以钉住规则；理论说即便没有制度钉住，缺列加异质信念也会内生出周期。实证的保证金时间序列是测量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是财富再分配与缺列。完全市场里倒霉的乐观者已经事先对冲，崩溃不必伴随杠杆跳。缺抵押这一列时，乐观者的损失不能被 Arrow 支付补回，他们的风险承担能力与他们的财富绑死——与 He–Krishnamurthy 同族，但约束来自抵押合同而不是激励合同。信息对称（大家都看见同一公共冲击）仍可以有周期：异质的是解释冲击的信念，或是估值。</p><p>与美人竞赛：高阶可以放大公共噪声；杠杆周期放大的是资产负债表。两者都能让价格相对股利更抖，通道不同。</p><p><span class="marginnote">「杠杆比利率更重要」是 Geanakoplos 的口号：有时利率几乎不变，保证金已经让有效融资成本跳了。这是对只盯 \\(r_f\\) 的宏观的批评，本课点到为止。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CDO 的结构图。下一课把资金约束接到 CAPM 的切点加总：谁不能持有市场时，beta 定价哪一段还成立。杠杆周期提供「约束谁、何时紧」；CAPM 偏离提供「截面上谁的期望回报被扭曲」。</p><p>后课默认：杠杆可以是均衡内生的抵押条款；繁荣加杠杆、崩溃去杠杆，价格反馈超过信念更新。与 BP 的 VaR 保证金互补，不是互相否证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>抵押债在缺列时充当赌注，均衡决定 haircut。</li><li>财富向乐观者集中时杠杆升，反向则强制去杠杆。</li><li>通道是资产负债表，不是高阶信念，也不是限价簿撤单。</li><li>出处：Geanakoplos, <em>NBER Macro Annual</em> 2010；Fostel and Geanakoplos。</li></ul>',10))])}const C=t(d,[["render",h]]);export{f as __pageData,C as default};
